WITH enriched AS (SELECT *, DENSE_RANK() OVER (ORDER BY price NULLS LAST) AS price_dense_rank, LEAD(cost, 1) OVER (ORDER BY stock_qty, id) AS next_cost, LAG(stock_qty, 2, 0) OVER (PARTITION BY brand ORDER BY stock_qty, id) AS prev_stock_qty, SUM(price) OVER (PARTITION BY brand ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_price FROM products) SELECT brand, APPROX_PERCENTILE(next_cost, 0.95) AS next_cost_p95, BIT_AND(stock_qty) AS stock_qty_bit_and, SORT_ARRAY(COLLECT_SET(brand)) AS brand_list, COUNT_IF(brand = 'Stark') AS stark_events, COUNT(DISTINCT category) AS distinct_categories FROM enriched GROUP BY brand
